def max_value_on_paths(N, grid_values):
    # Initialize the dynamic programming table
    dp = [[0] * (N+1) for _ in range(N+1)]

    # Loop through the grid values and update the dynamic programming table
    for x, y, value in grid_values:
        dp[x][y] = max(dp[x][y], dp[x-1][y] + value, dp[x][y-1] + value)

    # Return the maximum value in the final column of the dynamic programming table
    return max(dp[-1])
