def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a two-dimensional table to store the results of subproblems
    # The table will have n+1 rows and V+1 columns
    table = [[0] * (V + 1) for _ in range(n + 1)]

    # Fill the table with the values for the base case
    # In this case, the minimum remaining space when there are no items is equal to the total capacity of the box
    for i in range(V + 1):
        table[0][i] = i

    # Fill the table with the values for the other cases
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            # If the current volume is less than or equal to the capacity of the box, we can include the item
            if volumes[i - 1] <= j:
                table[i][j] = max(table[i - 1][j], table[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            # Otherwise, we cannot include the item and the minimum remaining space is the same as before
            else:
                table[i][j] = table[i - 1][j]

    # Return the minimum remaining space, which is the difference between the total capacity and the maximum occupied volume
    return V - table[n][V]

